args.test:
for bad in [0, -1, 10, 100]:
    try:
        moving_average([1,2,3], bad)
        raise AssertionError('window=%s 应抛 ValueError' % bad)
    except ValueError:
        pass
try:
    moving_average([1,2,3], 2.5)
    raise AssertionError('非整数 window 应抛 TypeError')
except TypeError:
    pass

assert moving_average([5], 1) == [5.0]
assert moving_average([1,2,3,4], 2) == [1.5, 2.5, 3.5]
try:
    moving_average([1,2,3], 2.5)
    raise AssertionError('应抛 TypeError')
except TypeError:
    pass
for bad in [0, -1, 10]:
    try:
        moving_average([1,2,3], bad)
        raise AssertionError('window=%s 应抛 ValueError' % bad)
    except ValueError:
        pass
